# Zstandard (ZSTD) – .blend compression, required.
build() {
  unpack ZSTD
  CMAKE_SOURCE_SUBDIR=build/cmake cmake_build \
    -DZSTD_BUILD_PROGRAMS=OFF -DZSTD_BUILD_SHARED=OFF -DZSTD_BUILD_STATIC=ON \
    -DZSTD_BUILD_TESTS=OFF -DZSTD_LEGACY_SUPPORT=OFF -DZSTD_LZ4_SUPPORT=OFF \
    -DZSTD_LZMA_SUPPORT=OFF -DZSTD_MULTITHREAD_SUPPORT=ON -DZSTD_ZLIB_SUPPORT=OFF
}
